import type { Editor } from "@tiptap/core";

export interface ToolbarComponentProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

import type { Editor } from "@tiptap/core";
import { Markdown as TiptapMarkdown } from "@tiptap/markdown";
import type { MarkdownExtensionOptions as TiptapMarkdownOptions } from "@tiptap/markdown";
import { Plugin, PluginKey } from "@tiptap/pm/state";

export interface MarkdownOptions extends TiptapMarkdownOptions {
  pasteMarkdown: boolean;
}

const MARKDOWN_PATTERN =
  /^(#{1,6}\s|>\s|[-*+]\s|\d+\.\s|```|---\s*$|\|.+\|)|\*\*[^*]+\*\*|__[^_]+__|~~[^~]+~~|`[^`]+`|!?\[[^\]]*\]\([^)]+\)/m;

export const looksLikeMarkdown = (text: string) => MARKDOWN_PATTERN.test(text);

export const markdownPastePluginKey = new PluginKey("markdownPaste");

export const downloadMarkdown = (editor: Editor, filename = "document.md") => {
  const url = URL.createObjectURL(
    new Blob([editor.getMarkdown()], { type: "text/markdown" })
  );
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
};

export const copyMarkdown = (editor: Editor) =>
  navigator.clipboard.writeText(editor.getMarkdown());

export const importMarkdownFile = (editor: Editor) => {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".md,.markdown,text/markdown,text/plain";
  input.addEventListener("change", async () => {
    const text = await input.files?.[0]?.text();
    if (text !== undefined && !editor.isDestroyed) {
      editor
        .chain()
        .focus()
        .setContent(text, { contentType: "markdown" })
        .run();
    }
  });
  input.click();
};

export const Markdown = TiptapMarkdown.extend<MarkdownOptions>({
  addOptions() {
    return {
      ...(this.parent?.() as TiptapMarkdownOptions),
      pasteMarkdown: false,
    };
  },

  addProseMirrorPlugins() {
    const parent = this.parent?.() ?? [];
    if (!this.options.pasteMarkdown) {
      return parent;
    }
    const { editor } = this;
    return [
      ...parent,
      new Plugin({
        key: markdownPastePluginKey,
        props: {
          handlePaste: (view, event) => {
            const data = event.clipboardData;
            const text = data?.getData("text/plain");
            const fromCodeEditor = data?.types.includes("vscode-editor-data");
            if (
              !text ||
              !editor.markdown ||
              (data?.getData("text/html") && !fromCodeEditor) ||
              view.state.selection.$from.parent.type.spec.code ||
              !looksLikeMarkdown(text)
            ) {
              return false;
            }
            return editor.commands.insertContent(editor.markdown.parse(text));
          },
        },
      }),
    ];
  },
});

"use client";

import type { Editor } from "@tiptap/core";
import { Copy, FileDown, FileText, FileUp } from "lucide-react";
import { useState } from "react";

import { copyMarkdown, downloadMarkdown, importMarkdownFile } from ".";
import { useToolbar, useToolbarEditor } from "../core/context";
import { useEditorState } from "../core/editor-state";
import type { ToolbarComponentProps } from "../core/types";
import { Button } from "../ui/button";
import { DropdownMenuItem } from "../ui/dropdown-item";
import { Popover } from "../ui/popover";
import { PopoverContent } from "../ui/popover-content";

export interface MarkdownToolbarProps extends ToolbarComponentProps {
  filename?: string;
}

export const MarkdownToolbar = ({
  className,
  editor: editorProp,
  filename,
}: MarkdownToolbarProps) => {
  const { labels } = useToolbar();
  const editor = useToolbarEditor(editorProp);
  const [open, setOpen] = useState(false);

  const disabled =
    useEditorState(editor, (edit) => edit.isDestroyed || !edit.markdown) ??
    true;

  const run = (action: (target: Editor) => unknown) => {
    setOpen(false);
    if (editor && !disabled) {
      action(editor);
    }
  };

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      side="bottom"
      align="start"
      sideOffset={6}
      trigger={
        <Button
          aria-label={labels.markdown}
          className={["ext-btn--icon-sm", className].filter(Boolean).join(" ")}
          disabled={disabled}
          tooltip={labels.markdown}
        >
          <FileText />
        </Button>
      }
    >
      <PopoverContent role="menu" style={{ minWidth: "11rem", padding: 4 }}>
        <DropdownMenuItem onClick={() => run(importMarkdownFile)}>
          <FileUp />
          {labels.importMarkdown}
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={() => run((target) => downloadMarkdown(target, filename))}
        >
          <FileDown />
          {labels.exportMarkdown}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => run(copyMarkdown)}>
          <Copy />
          {labels.copyMarkdown}
        </DropdownMenuItem>
      </PopoverContent>
    </Popover>
  );
};

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import type { CSSProperties, ReactNode, ReactPortal } from "react";
import { createPortal } from "react-dom";

export type FloatingSide = "bottom" | "top" | "left" | "right";
export type FloatingAlign = "start" | "center" | "end";

export interface UseFloatingOptions {
  align?: FloatingAlign;
  onOpenChange?: (open: boolean) => void;
  open: boolean;
  side?: FloatingSide;
  sideOffset?: number;
}

const clamp = (value: number, max: number): number =>
  Math.max(8, Math.min(value, Math.max(8, max)));

export const useFloating = ({
  align = "center",
  onOpenChange,
  open,
  side = "bottom",
  sideOffset = 4,
}: UseFloatingOptions) => {
  const triggerRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  const close = useCallback(() => {
    onOpenChange?.(false);
  }, [onOpenChange]);

  const applyPosition = useCallback(() => {
    const trigger = triggerRef.current;
    const content = contentRef.current;
    if (!(trigger instanceof HTMLElement) || !content) {
      return;
    }
    const rect = trigger.getBoundingClientRect();
    const width = content.offsetWidth;
    const height = content.offsetHeight;

    let left: number | undefined;
    let top: number | undefined;
    let right: number | undefined;
    let bottom: number | undefined;
    const translate: string[] = [];

    if (side === "bottom" || side === "top") {
      if (side === "bottom") {
        top = clamp(rect.bottom + sideOffset, window.innerHeight - height);
      } else {
        bottom = window.innerHeight - rect.top + sideOffset;
      }
      if (align === "center") {
        left = clamp(rect.left + rect.width / 2, window.innerWidth - width);
        translate.push("translateX(-50%)");
      } else if (align === "end") {
        right = clamp(
          window.innerWidth - rect.right,
          window.innerWidth - width
        );
      } else {
        left = clamp(rect.left, window.innerWidth - width);
      }
    } else {
      if (side === "right") {
        left = clamp(rect.right + sideOffset, window.innerWidth - width);
      } else {
        right = window.innerWidth - rect.left + sideOffset;
      }
      if (align === "center") {
        top = clamp(rect.top + rect.height / 2, window.innerHeight - height);
        translate.push("translateY(-50%)");
      } else if (align === "end") {
        bottom = window.innerHeight - rect.bottom;
      } else {
        top = clamp(rect.top, window.innerHeight - height);
      }
    }

    content.style.left = left === undefined ? "" : `${left}px`;
    content.style.top = top === undefined ? "" : `${top}px`;
    content.style.right = right === undefined ? "" : `${right}px`;
    content.style.bottom = bottom === undefined ? "" : `${bottom}px`;
    content.style.transform = translate.join(" ");
  }, [align, side, sideOffset]);

  useLayoutEffect(() => {
    if (!open) {
      return;
    }
    applyPosition();
    const handleScroll = () => {
      applyPosition();
    };
    const handleResize = () => {
      applyPosition();
    };
    window.addEventListener("scroll", handleScroll, true);
    window.addEventListener("resize", handleResize);
    // The trigger can also move without a scroll or resize — a table grip
    // shifts when its row or column is added or deleted. Follow it per frame
    // so the open menu never detaches from its trigger.
    let frame: number;
    const follow = () => {
      applyPosition();
      frame = requestAnimationFrame(follow);
    };
    frame = requestAnimationFrame(follow);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", handleScroll, true);
      window.removeEventListener("resize", handleResize);
    };
  }, [applyPosition, open]);

  useEffect(() => {
    if (!open) {
      return;
    }
    const handlePointerDown = (e: PointerEvent) => {
      const target = e.target as HTMLElement | null;
      if (
        target &&
        (triggerRef.current?.contains(target) ||
          contentRef.current?.contains(target))
      ) {
        return;
      }
      close();
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        close();
      }
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [close, open]);

  const content = (children: ReactNode): null | ReactPortal =>
    open
      ? createPortal(
          <div
            ref={contentRef}
            data-ext-floating
            style={{ position: "fixed", zIndex: 60 } as CSSProperties}
          >
            {children}
          </div>,
          document.body
        )
      : null;

  return { content, triggerRef };
};

import * as React from "react";

import { useFloating } from "./use-floating";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  active?: boolean;
  danger?: boolean;
  tooltip?: string;
}

const PlainButton = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className = "",
      active = false,
      danger = false,
      tooltip: _tooltip,
      type = "button",
      ...props
    },
    ref
  ) => {
    const cls = [
      "ext-btn",
      active ? "ext-btn--active" : "",
      danger ? "ext-btn--danger" : "",
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <button
        ref={ref}
        type={type}
        className={cls}
        data-state={active ? "on" : "off"}
        aria-pressed={active}
        {...props}
      />
    );
  }
);
PlainButton.displayName = "PlainButton";

const TooltipButton = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      tooltip,
      onBlur,
      onFocus,
      onPointerDown,
      onPointerEnter,
      onPointerLeave,
      ...props
    },
    ref
  ) => {
    const [open, setOpen] = React.useState(false);
    const { content, triggerRef } = useFloating({
      onOpenChange: setOpen,
      open,
      sideOffset: 6,
    });

    const setRef = (node: HTMLButtonElement | null) => {
      triggerRef.current = node;
      if (typeof ref === "function") {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    };

    return (
      <>
        <PlainButton
          ref={setRef}
          onBlur={(event) => {
            setOpen(false);
            onBlur?.(event);
          }}
          onFocus={(event) => {
            setOpen(event.currentTarget.matches(":focus-visible"));
            onFocus?.(event);
          }}
          onPointerDown={(event) => {
            setOpen(false);
            onPointerDown?.(event);
          }}
          onPointerEnter={(event) => {
            setOpen(true);
            onPointerEnter?.(event);
          }}
          onPointerLeave={(event) => {
            setOpen(false);
            onPointerLeave?.(event);
          }}
          {...props}
        />
        {content(
          <div className="ext-tooltip" role="tooltip">
            {tooltip}
          </div>
        )}
      </>
    );
  }
);
TooltipButton.displayName = "TooltipButton";

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>((props, ref) =>
  props.tooltip ? (
    <TooltipButton ref={ref} {...props} />
  ) : (
    <PlainButton ref={ref} {...props} />
  )
);
Button.displayName = "Button";

export { Button };

import * as React from "react";

export interface DropdownMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  danger?: boolean;
}

const DropdownMenuItem = React.forwardRef<
  HTMLButtonElement,
  DropdownMenuItemProps
>(({ className = "", danger = false, type = "button", ...props }, ref) => {
  const cls = [
    "ext-dropdown-item",
    danger ? "ext-dropdown-item--danger" : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <button
      ref={ref}
      type={type}
      role="menuitem"
      data-dropdown-item
      className={cls}
      {...props}
    />
  );
});
DropdownMenuItem.displayName = "DropdownMenuItem";

export { DropdownMenuItem };

import * as React from "react";
import { useCallback } from "react";

import { useFloating } from "./use-floating";
import type { FloatingAlign, FloatingSide } from "./use-floating";

export type PopoverAlign = FloatingAlign;
export type PopoverSide = FloatingSide;

export interface PopoverProps {
  align?: PopoverAlign;
  children: React.ReactNode;
  className?: string;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
  side?: PopoverSide;
  sideOffset?: number;
  trigger: React.ReactElement;
}

const Popover = ({
  align = "center",
  children,
  onOpenChange,
  open = false,
  side = "bottom",
  sideOffset = 4,
  trigger,
}: PopoverProps) => {
  const { content, triggerRef } = useFloating({
    align,
    onOpenChange,
    open,
    side,
    sideOffset,
  });

  const toggle = useCallback(() => {
    onOpenChange?.(!open);
  }, [onOpenChange, open]);

  const triggerWithHandlers = React.cloneElement(
    trigger as React.ReactElement<
      React.HTMLAttributes<HTMLElement> & { ref?: React.Ref<HTMLElement> }
    >,
    {
      "aria-expanded": open,
      "aria-haspopup": "dialog",
      onClick: toggle,
      ref: triggerRef,
    }
  );

  return (
    <>
      {triggerWithHandlers}
      {content(children)}
    </>
  );
};

Popover.displayName = "Popover";

export { Popover };

import * as React from "react";
import { useCallback, useLayoutEffect, useState } from "react";

export interface DropdownPillHandlers {
  onFocus: (event: React.FocusEvent<HTMLDivElement>) => void;
  onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => void;
  onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => void;
}

interface PillRect {
  height: number;
  left: number;
  top: number;
  width: number;
}

const measure = (item: HTMLElement): PillRect => ({
  height: item.offsetHeight,
  left: item.offsetLeft,
  top: item.offsetTop,
  width: item.offsetWidth,
});

const useDropdownPill = (
  onMouseLeave?: (event: React.MouseEvent<HTMLDivElement>) => void,
  activeItem?: HTMLElement | null
): { handlers: DropdownPillHandlers; pill: React.ReactNode } => {
  const [rect, setRect] = useState<PillRect | null>(null);

  useLayoutEffect(() => {
    if (activeItem) {
      setRect(measure(activeItem));
    }
  }, [activeItem]);

  const handleItemEnter = useCallback((target: EventTarget | null) => {
    const item = (target as HTMLElement).closest<HTMLElement>(
      "[data-dropdown-item]"
    );
    if (!item) {
      return;
    }
    setRect(measure(item));
  }, []);

  const handlers: DropdownPillHandlers = {
    onFocus: (event: React.FocusEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
    onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => {
      setRect(activeItem ? measure(activeItem) : null);
      onMouseLeave?.(event);
    },
    onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
  };

  const pill = (
    <div
      aria-hidden="true"
      className={["ext-dropdown-pill", rect ? "ext-dropdown-pill--visible" : ""]
        .filter(Boolean)
        .join(" ")}
      style={
        rect
          ? {
              height: rect.height,
              left: rect.left,
              top: rect.top,
              width: rect.width,
            }
          : undefined
      }
    />
  );

  return { handlers, pill };
};

export { useDropdownPill };

import * as React from "react";

import { useDropdownPill } from "./dropdown-pill";

export type PopoverContentProps = React.HTMLAttributes<HTMLDivElement>;

const PopoverContent = React.forwardRef<HTMLDivElement, PopoverContentProps>(
  ({ className = "", onMouseLeave, ...props }, ref) => {
    const { handlers, pill } = useDropdownPill(onMouseLeave);

    return (
      <div
        ref={ref}
        className={`ext-popover-content ${className}`.trim()}
        {...handlers}
        {...props}
      >
        {pill}
        {props.children}
      </div>
    );
  }
);
PopoverContent.displayName = "PopoverContent";

export { PopoverContent };

/* Extensions UI primitives using shadcn CSS variables */

@keyframes ext-pop-in {
  from {
    opacity: 0;
    translate: 0 0.25rem;
    scale: 0.95;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}

/* ── Button ── */
.ext-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 0.375rem;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 2px);
  background: transparent;
  color: inherit;
  font-size: 0.8125rem;
  font-family: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    border-color 150ms ease-out,
    transform 100ms ease-out;
}

.ext-btn > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-btn--icon {
  width: 2rem;
  padding: 0;
}

.ext-btn--icon-sm {
  width: 1.75rem;
  padding: 0;
}

.ext-btn:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

.ext-btn:active {
  transform: scale(0.96);
}

.ext-btn:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-btn--active {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn--danger {
  color: var(--destructive, #ef4444);
}

.ext-btn--danger:hover {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

/* ── Dropdown ── */
.ext-dropdown-content {
  position: relative;
  min-width: 10rem;
  padding: 0.25rem;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-dropdown-item {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.375rem 0.5rem;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--popover-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.ext-dropdown-item > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-dropdown-pill {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: calc(var(--radius) - 4px);
  background: color-mix(in srgb, var(--primary) 6%, transparent);
  opacity: 0;
  transition:
    top 220ms cubic-bezier(0.22, 1, 0.36, 1),
    left 220ms cubic-bezier(0.22, 1, 0.36, 1),
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    height 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 150ms ease-out;
}

.ext-dropdown-pill--visible {
  opacity: 1;
}

.ext-dropdown-item:hover,
.ext-dropdown-item:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-dropdown-item:active {
  transform: scale(0.98);
}

.ext-dropdown-item:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-dropdown-item--danger {
  color: var(--destructive, #ef4444);
}

.ext-dropdown-item--danger:hover,
.ext-dropdown-item--danger:focus-visible {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

.ext-dropdown-separator {
  height: 1px;
  background: var(--border);
  margin: 0.25rem 0;
}

/* ── Popover ── */
.ext-popover-content {
  position: relative;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* ── Tooltip ── */
.ext-tooltip {
  padding: 0.375rem 0.75rem;
  border-radius: 0;
  background: var(--foreground);
  color: var(--background);
  font-size: 0.75rem;
  line-height: 1rem;
  white-space: nowrap;
  pointer-events: none;
  animation: ext-pop-in 0.12s ease-out forwards;
}

/* ── Separator ── */
.ext-separator {
  flex-shrink: 0;
  background: var(--border);
}

.ext-separator--horizontal {
  height: 1px;
  margin: 0.25rem 0;
}

.ext-separator--vertical {
  width: 1px;
  height: 1rem;
  align-self: center;
  margin: 0 0.25rem;
}

/* ── Input ── */
.ext-input {
  width: 100%;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  background: var(--background);
  color: var(--foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  transition:
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-input::placeholder {
  color: var(--muted-foreground);
}

.ext-input:focus-visible {
  border-color: var(--ring);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ring) 30%, transparent);
}

/* ── Tabs ── */
.ext-tabs {
  display: flex;
  flex-direction: column;
}

.ext-tabs-list {
  display: flex;
  gap: 0.125rem;
  width: fit-content;
  padding: 0.25rem;
  border-radius: calc(var(--radius) - 4px);
  background: var(--muted);
}

.ext-tabs-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border: none;
  border-radius: calc(var(--radius) - 6px);
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out;
}

.ext-tabs-trigger > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-tabs-trigger:hover,
.ext-tabs-trigger:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-tabs-trigger--active {
  background: var(--background);
  color: var(--foreground);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.ext-tabs-content {
  padding-top: 0.5rem;
}
